import{_ as n,C as a,c as i,o as l,a9 as c,G as r}from"./chunks/framework.BMko4Wr3.js";const k=JSON.parse('{"title":"配置文件","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/Terra"},{"title":"配置文件","link":"/Terra/config-packs.config-development.config-files"}]},"headers":[],"relativePath":"Terra/config-packs.config-development.config-files.md","filePath":"Terra/config-packs.config-development.config-files.md"}'),s={name:"Terra/config-packs.config-development.config-files.md"};function p(d,e,f,h,m,_){const o=a("NolebaseGitContributors"),t=a("NolebaseGitChangelog");return l(),i("div",null,[e[0]||(e[0]=c('<h1 id="配置文件" tabindex="-1">配置文件 <a class="header-anchor" href="#配置文件" aria-label="Permalink to &quot;配置文件&quot;">​</a></h1><p>配置开发的主要内容即创建与编写<a href="https://en.wikipedia.org/wiki/Configuration_file" target="_blank" rel="noreferrer">配置文件</a>。<em>在开发配置的语境中</em>，配置文件（或简称<em>配置</em>）是一系列包含了地形包的文件，能够控制 Terra 生成世界的方式。</p><h2 id="文件格式" tabindex="-1">文件格式 <a class="header-anchor" href="#文件格式" aria-label="Permalink to &quot;文件格式&quot;">​</a></h2><p>通常，配置文件要求其内的数据能够<a href="https://en.wikipedia.org/wiki/Serialization" target="_blank" rel="noreferrer">序列化</a>，这就表示其格式通常为 JSON、XML 或是 YAML。</p><p>在 Terra 中，地形包的配置格式灵活多变，对它们的读取和判断均通过拓展实现——这允许开发者随意使用想要的格式。在地形包中的对应格式配置文件只会在安装对应<strong>语言拓展</strong>的情况下载入。</p><h3 id="yaml" tabindex="-1">YAML <a class="header-anchor" href="#yaml" aria-label="Permalink to &quot;YAML&quot;">​</a></h3><p>这是 Terra 配置支持的标准文件格式/标记语言，标准的 Terra 发行版自带对其支持的拓展模块。正因如此，YAML 是本维基的首选标记语言，所有示例配置与教程均使用它展示。</p><p>YAML 语言拓展会尝试载入地形包内所有 <code>.yml</code> 结尾的文件，同时其内容应当能被 <a href="https://yaml.org/spec/" target="_blank" rel="noreferrer">YAML 判断器</a>识别。</p><h2 id="创建配置文件" tabindex="-1">创建配置文件 <a class="header-anchor" href="#创建配置文件" aria-label="Permalink to &quot;创建配置文件&quot;">​</a></h2><p>如果你没有安装其他语言拓展，那么你可以先在地形包文件夹下创建一个 <code>.yml</code> 文件，作为标准的配置文件。</p><p>否则，在创建新文件的时候，你应当选择<em>语言拓展</em>支持的格式。</p><h3 id="配置文件结构" tabindex="-1">配置文件结构 <a class="header-anchor" href="#配置文件结构" aria-label="Permalink to &quot;配置文件结构&quot;">​</a></h3><p>通常来讲，配置文件的名称与地形包中的子文件夹不会被 Terra 读取。正因如此，你可以随意命名文件或组织文件夹结构。但包文件例外，它必须处于最上级目录中，且名称只能是 <code>pack</code>（不需要文件后缀）。</p>',13)),r(o),r(t)])}const b=n(s,[["render",p]]);export{k as __pageData,b as default};
